import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`document-proofreader`,heroTitle:`Proofread your document in minutes`,heroSubtitle:`Perplexity Computer reads every line, catches grammar and style issues, and delivers a clean corrected version — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Proofread my document`,inputFileAccept:`.pdf,.doc,.docx,.txt`,inputFilePrefill:`Proofread the uploaded document line by line. Check for grammar, spelling, and punctuation errors. Review style consistency, tone, voice, and word choice throughout. Flag unclear phrasing, redundant language, and awkward constructions. Then deliver a clean corrected version of the document with tracked changes showing every edit, plus a summary report organized by: 1) Grammar and spelling fixes, 2) Punctuation corrections, 3) Style and tone consistency improvements, 4) Word choice and clarity enhancements.`,heroOverlaySteps:[`Reading every line and checking grammar, spelling, and punctuation`,`Reviewing style consistency, tone, voice, and word choice throughout`,`Flagging unclear phrasing, redundancy, and awkward constructions`,`Clean corrected version with tracked changes — ready to publish`],generatingSteps:[`Reading your document to understand scope, tone, and style`,`Designing an agent to check grammar, spelling, punctuation, and consistency`,`Configuring style review and word choice analysis across the full document`,`Setting up the corrected document with tracked changes and summary report`],featureSectionTitle:`From draft to clean copy`,featureCardTitles:[`Connects to your writing stack`,`Clean copy, ready to publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Notion, Grammarly, Dropbox, OneDrive — Computer plugs into your tools so proofreading flows straight into your writing workflow.`,`Corrected document with tracked changes. Grammar fixes. Style improvements. Word choice refinements. Computer delivers a polished version you can publish immediately.`],capabilitySectionTitle:`Your proofreader, on demand`,capabilitySectionSubtitle:`Upload a document, step away, come back to a clean corrected version.`,capabilityCards:[{title:`Deep Proofreading`,description:`Computer can read every line of your document — reports, articles, manuscripts, emails — and catch grammar, spelling, and punctuation errors humans miss.`},{title:`Style Consistency`,description:`Computer can flag tone shifts, voice inconsistencies, and formatting mismatches — ensuring your document reads as one cohesive piece from start to finish.`},{title:`Word Choice`,description:`Computer can identify unclear phrasing, redundant language, and awkward constructions — and suggest precise alternatives that sharpen your writing.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Docs, Notion, Dropbox, OneDrive, and more — build proofreading workflows across your entire stack.`},{title:`Remember & Learn`,description:`Computer can remember your style guides, terminology preferences, and past corrections — so every proofread gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can watch shared folders for new documents and trigger proofreading automatically — pinging you when a clean version is ready.`}]});export{t as default};
